type counter struct{ n int }                 // one owner, no package-level state

func (c *counter) HandleClick(w http.ResponseWriter, r *http.Request) {
    c.n++                                     // state lives with the handler
    fmt.Fprintf(w, "pressed %d times", c.n)
}

func search(w http.ResponseWriter, r *http.Request) {
    query := r.URL.Query().Get("q")           // request-scoped: stays local
    _ = query
}
